#!/bin/bash
# Generated by /scaffold from .claude/templates/init-sh.template (verification mode: local).
# Single command: install, build the UI, then start MediCard on http://localhost:8000 with seed data.
set -euo pipefail

echo "=== Bootstrapping MediCard dev environment ==="

# Backend dependencies
poetry install --no-interaction

# Frontend dependencies + production build (served by FastAPI at /)
(cd frontend && npm ci && npm run build)

# Environment
if [ -f ".env.example" ] && [ ! -f ".env" ]; then
  cp .env.example .env
  echo "Created .env from .env.example"
fi

# Local services (no Docker in local verification mode)
poetry run medicard &
APP_PID=$!
trap 'kill $APP_PID 2>/dev/null || true' INT TERM

# Health checks
echo "Waiting for services..."
for i in 1 2 3 4 5; do
  if curl -fsS http://localhost:8000/health >/dev/null 2>&1; then
    echo "=== Environment ready: http://localhost:8000 ==="
    wait $APP_PID
    exit 0
  fi
  sleep $((i * 2))
done
echo "Health check failed at http://localhost:8000/health" >&2
exit 1
